function Refresh-HZAccountsCenter([bool]$forceCloud=$false){
 if($null-eq$script:ucpList){return};$sel='';try{$sel=[string]$script:ucpList.SelectedItem.Id}catch{};Load-HZAccounts;$cloud=@(Get-HZCloudSessionsSafe $forceCloud);Sync-HZAccountsFromCloud $cloud;$script:ucpProfiles=@($script:accounts|Sort-Object LastUsed -Descending);$v=@();$on=0
 foreach($a in @($script:ucpProfiles)){$s=Get-HZUcpStatus $a $cloud;if($s-ne'OFFLINE'){$on++};$n=@(Get-HZAccountRules $a).Count;$i=Get-HZScalarInt $a.ServerIndex -1;$sv=$(if($i-ge0){'Horizonte RP #'+($i+1)}else{[string]$a.Host});$bg='#172638';$fg='#A9C5D8';if($s-match'BLOQUEADA|RECUSADO|ERRO'){$bg='#40202B';$fg='#FFB7C3'}elseif($s-match'AGUARDANDO|CONECTANDO|ENTRANDO'){$bg='#3A321C';$fg='#FFD778'}elseif($s-ne'OFFLINE'-and$s-notmatch'OFFLINE'){$bg='#123B30';$fg='#69F0B0'};$v+=[pscustomobject]@{Id=[string]$a.Id;Status=$s;Bg=$bg;Fg=$fg;Nick=[string]$a.Nickname;Server=$sv;Rules=('login rápido: '+$n)}}
 $script:ucpList.ItemsSource=$null;$script:ucpList.ItemsSource=@($v);$script:ucpSummary.Text=$v.Count.ToString()+' contas salvas • '+$on.ToString()+' ativas';$hit=$false;if($sel){for($i=0;$i-lt$v.Count;$i++){if([string]$v[$i].Id-eq$sel){$script:ucpList.SelectedIndex=$i;$hit=$true;break}}};if(!$hit-and$v.Count){$script:ucpList.SelectedIndex=0}
}
function Get-HZUcpSelected{if($null-eq$script:ucpList-or$null-eq$script:ucpList.SelectedItem){return $null};Get-HZAccountById -id ([string]$script:ucpList.SelectedItem.Id)}
function Open-HZUcpConnection([string]$id){$a=Get-HZAccountById -id $id;if($null-eq$a){throw'Conta indisponível.'};$idx=Get-HZScalarInt $a.ServerIndex -1;$nick=([string]$a.Nickname).Trim();$p=$null;foreach($x in @($script:hzAccountPages)){if([string]$x.AccountId-eq$id){$p=$x;break}};if($null-eq$p){foreach($x in @($script:hzAccountPages)){if(([string]$x.Nick).Equals($nick,[StringComparison]::OrdinalIgnoreCase)-and[int]$x.ServerIndex-eq$idx){$p=$x;break}}};if($null-eq$p){throw'Conta sem página de conexão.'};$p.AccountId=$id;$p.Nick=$nick;$p.ServerIndex=$idx;Save-HZAccountPages;Select-HZAccountPage ([string]$p.Id);Show-HZConnectionCenter}
function Show-HZAccountsCenter{
 if($env:HZ_MULTI_CHILD-eq'1'){return};$script:ucpOpenConnectionId='';$ux=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Centro de Contas" Width="1020" Height="650" WindowStartupLocation="CenterOwner" Background="#07111D" FontFamily="Segoe UI"><Window.Resources><DataTemplate x:Key="R"><Border Background="#0A1826" BorderBrush="#1B425D" BorderThickness="1" CornerRadius="10" Padding="12,10"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="175"/><ColumnDefinition Width="150"/><ColumnDefinition Width="190"/><ColumnDefinition Width="135"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Border Background="{Binding Bg}" CornerRadius="12" Padding="9,5" HorizontalAlignment="Left"><StackPanel Orientation="Horizontal"><Ellipse Width="7" Height="7" Fill="{Binding Fg}" Margin="0,0,6,0"/><TextBlock Text="{Binding Status}" Foreground="{Binding Fg}" FontWeight="Bold"/></StackPanel></Border><TextBlock Grid.Column="1" Text="{Binding Nick}" Foreground="#F3F8FC" FontWeight="SemiBold" FontSize="13" VerticalAlignment="Center"/><TextBlock Grid.Column="2" Text="{Binding Server}" Foreground="#BFD5E6" VerticalAlignment="Center"/><TextBlock Grid.Column="3" Text="{Binding Rules}" Foreground="#91AABD" VerticalAlignment="Center"/><Button x:Name="OpenChat" Grid.Column="4" Tag="{Binding Id}" Content="CONEXÕES E CHAT" Background="#087FE0" Foreground="White" BorderBrush="#18A9FF" FontWeight="Bold" Padding="14,9" HorizontalAlignment="Right"/></Grid></Border></DataTemplate></Window.Resources><Grid Margin="23"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="CONTAS E SESSÕES" Foreground="White" FontSize="24" FontWeight="Bold"/><TextBlock Text="Sessões 24/7 na Discloud • acesso rápido por conta" Foreground="#7895AA"/></StackPanel><Button x:Name="Refresh" Grid.Column="1" Content="↻ ATUALIZAR" Background="#12283B" Foreground="#BFEAFF" BorderBrush="#285A76" Padding="14,8"/></Grid><TextBlock x:Name="Summary" Grid.Row="1" Text="Carregando..." Foreground="#64DDA2" Margin="0,17,0,10"/><Border Grid.Row="2" Background="#081521" BorderBrush="#18364C" BorderThickness="1" CornerRadius="11"><ListBox x:Name="Accounts" Background="Transparent" BorderThickness="0" ItemTemplate="{StaticResource R}" HorizontalContentAlignment="Stretch"/></Border><Grid Grid.Row="3" Margin="0,14,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><Button x:Name="SaveCurrent" Content="SALVAR CONTA ATUAL" Background="#17273A" Foreground="#DCEBFA" BorderBrush="#31506D" Padding="12,9" Margin="0,0,8,0"/><Button x:Name="Cloud" Grid.Column="1" Content="☁ CONECTAR 24/7" Background="#103C2D" Foreground="#79F0B0" BorderBrush="#23895D" Padding="12,9" Margin="0,0,8,0"/><Button x:Name="Stop" Grid.Column="2" Content="DESCONECTAR" Background="#422028" Foreground="#FFC3CA" BorderBrush="#71313C" Padding="12,9"/><Button x:Name="Delete" Grid.Column="4" Content="EXCLUIR PERFIL" Background="#251A20" Foreground="#E1AEBB" BorderBrush="#633541" Padding="12,9"/></Grid></Grid></Window>
'@;$r=New-Object System.Xml.XmlNodeReader([xml]$ux);$d=[Windows.Markup.XamlReader]::Load($r);$d.Owner=$window;$script:ucpWindow=$d;$script:ucpList=$d.FindName('Accounts');$script:ucpSummary=$d.FindName('Summary')
 $d.AddHandler([Windows.Controls.Button]::ClickEvent,[Windows.RoutedEventHandler]{param($o,$e);$b=$e.Source;if($b-is[Windows.Controls.Button]-and$b.Name-eq'OpenChat'){$script:ucpOpenConnectionId=[string]$b.Tag;$script:ucpWindow.Close();$e.Handled=$true}});$d.FindName('Refresh').Add_Click({Refresh-HZAccountsCenter $true});$d.FindName('SaveCurrent').Add_Click({try{$null=Ensure-HZAccountCurrent;Refresh-HZAccountsCenter}catch{}})
 $d.FindName('Cloud').Add_Click({try{$a=Get-HZUcpSelected;if($null-eq$a){return};$c=@(Get-HZAccountRules $a).Count;$busy=$false;try{$busy=($script:process-and!$script:process.HasExited)}catch{};if($busy-and$c-lt1){throw'Faça o primeiro login desta conta antes de usar outra sessão.'};Start-HZAccountCloud $a (!$busy);Refresh-HZAccountsCenter $true}catch{[Windows.MessageBox]::Show($_.Exception.Message,'Horizonte AFK')|Out-Null}})
 $d.FindName('Stop').Add_Click({try{$a=Get-HZUcpSelected;if($null-eq$a){return};$sid=Get-HZAccountCloudSessionId $a;foreach($c in @(Get-HZCloudSessionsSafe)){if([string]$c.session_id-eq$sid){$null=Invoke-HZCloudApi 'POST' ('/v1/client/sessions/'+$sid+'/stop') @{confirm=$true} 8}};Stop-HZAccountLocalSession -id ([string]$a.Id);Stop-HZAdditiveMultiSessionForAccount -id ([string]$a.Id);Stop-HZPageSessionForAccount -accountId ([string]$a.Id);try{if([string]$script:activeAccountId-eq[string]$a.Id-and$script:process-and!$script:process.HasExited){Stop-Client}}catch{};if([string]$script:cloudSessionId-eq$sid){Detach-HZCloudUi};Refresh-HZAccountsCenter $true}catch{}})
 $d.FindName('Delete').Add_Click({$a=Get-HZUcpSelected;if($null-eq$a){return};if([Windows.MessageBox]::Show(('Excluir o perfil salvo de '+[string]$a.Nickname+'?'),'Horizonte AFK',[Windows.MessageBoxButton]::YesNo)-ne[Windows.MessageBoxResult]::Yes){return};$id=[string]$a.Id;$script:accounts=@($script:accounts|Where-Object{[string]$_.Id-ne$id});Save-HZAccounts;Save-HZDeviceRegistry;Refresh-HZAccountsCenter})
 Refresh-HZAccountsCenter $true;if($script:ucpRefreshTimer){try{$script:ucpRefreshTimer.Stop()}catch{}};$script:ucpRefreshTimer=New-Object Windows.Threading.DispatcherTimer;$script:ucpRefreshTimer.Interval=[TimeSpan]::FromSeconds(2);$script:ucpRefreshTimer.Add_Tick({try{Refresh-HZAccountsCenter}catch{}});$script:ucpRefreshTimer.Start();$null=$d.ShowDialog();try{$script:ucpRefreshTimer.Stop()}catch{};$script:ucpRefreshTimer=$null;$id=[string]$script:ucpOpenConnectionId;$script:ucpWindow=$null;$script:ucpList=$null;$script:ucpSummary=$null;$script:ucpProfiles=@();if($id){try{Open-HZUcpConnection $id}catch{[Windows.MessageBox]::Show($_.Exception.Message,'Horizonte AFK')|Out-Null}}
}
function Initialize-HZAccountCenter{if($env:HZ_TEST_MODE-eq'1'){return};if($env:HZ_MULTI_CHILD-ne'1'){Load-HZAccounts}else{if($AccountsButton){$AccountsButton.Visibility='Collapsed'};return};if($script:accountAutoTimer){try{$script:accountAutoTimer.Stop()}catch{}};$script:accountAutoTimer=New-Object Windows.Threading.DispatcherTimer;$script:accountAutoTimer.Interval=[TimeSpan]::FromMilliseconds(700);$script:accountAutoTimer.Add_Tick({try{Try-HZQuickAnswerMainDialog}catch{};try{Update-HZAccountLocalSessions}catch{}});$script:accountAutoTimer.Start()}
